//! The build half of the runtime route: three modules and one generated file.
//!
//! An SDK that ships the runtime route calls `createModule` in place of
//! `translate.createModule()` and imports what comes back as its `c` module.
//! Nothing here links the native library. That is the point: in this
//! configuration the symbols arrive through the platform loader at run time, and
//! linking the archive as well would make the linker demand them before `load`
//! ever runs.
//!
//!   rt        runtime/loader.zig, the reusable core. Pure Zig; imported by the
//!             facade in both configurations, because `LoadSource` and
//!             `LoadError` are this SDK's public types and must be the same
//!             types whichever configuration is built.
//!   library   runtime/library.zig, this SDK's descriptor: the namespaced
//!             synchronization binding and the load-time checks.
//!   dispatch  generated by runtime/generate.zig from the real translation
//!             output: the table, the wrappers, `load`, and the re-exported
//!             translated namespace. It imports `rt`, `library` and the
//!             generator's patched translation as `c_native`, which imports the
//!             dispatch back as `c_routed`.
//!   sync.c    compiled into the dispatch with
//!             `-DRT_SYNC_PREFIX=simdjson_rt`, so its symbols cannot collide
//!             with another SDK's.
//!
//! ## The one thing a caller must not do
//!
//! Do not link the compiled library into a module that imports this dispatch.
//! The facade's `c` import is the dispatch, and nothing else in the graph should
//! reference `libsimdjson`, or the linker resolves the same symbols statically
//! and the runtime route silently becomes a linked one.
//! `build_support/graph.zig:addGraph` is the seam: its runtime branch drops the
//! `module.linkLibrary(simdjson)` call that the linked branch keeps, and keeps
//! building and installing the artifact either way, because delivery and
//! dispatch are separate questions.
//!
//! ## Why `-Dlinkage` is not consulted here
//!
//! Delivery and dispatch are orthogonal for this SDK, and the reason is
//! structural rather than a preference. The only external symbols in the
//! translated header are the eleven entry points `zig/bridge.h` declares, and
//! all eleven come from the two C++ translation units this package compiles
//! (`src/src/simdjson.cpp` and `zig/bridge.cc`). Under `-Druntime` those units
//! are still built and installed — a provider is what they produce, and the
//! point of the mode is that a caller may name a provider this tree did not
//! build — but nothing in the consumer's link line refers to them.
//!
//! One consequence is worth stating because it decides how a caller must ask
//! for a provider. Under `-Druntime`, a *static* install cannot itself be the
//! provider: an archive is not something a platform loader can open. What a
//! runtime-loaded caller needs is either the shared object `-Dlinkage=dynamic`
//! installs, or some other shared object exporting the same eleven symbols.
//! `build.zig` says so at configure time rather than letting a caller discover
//! it as a missing file from the loader.
const std = @import("std");

/// The prefix `runtime/sync.c` is compiled with.
///
/// `runtime/library.zig` declares the same prefix in the symbol names it binds.
/// The two must agree, and a build where they do not fails to link, which is the
/// whole error report: there is no runtime path that could hide it.
///
/// A build that needs a second, independent instance of this SDK in one binary
/// should change this value *and* the prefix in `runtime/library.zig`, and then
/// give the second instance its own copy of both files. Nothing else in the
/// package assumes one instance.
const sync_prefix = "simdjson_rt";

/// The name this dispatch reports in its pre-load panic and in its header.
///
/// It is the package name, which is also the artifact name
/// (`build_support/graph.zig:artifact_name`), so the panic, the `.pc` record and
/// the module a dependent imports all name one thing.
const library_name = "simdjson";

/// `extern` declarations that the C library provides and that must therefore
/// stay direct.
///
/// This SDK declares none, and the reason is that the header this build
/// translates is not an upstream header at all: it is this fork's own
/// `zig/bridge.h`, whose entire include set is `<stddef.h>` and `<stdint.h>`
/// (`bridge.h:110-111`), and neither of those declares a function. Everything
/// upstream needs from a C library is reached from inside the *provider's*
/// compilation of the C++ bridge, not through a declaration the consumer's
/// translation can see.
///
/// The list is written out rather than left implicit because a name added to
/// `zig/bridge.h` is not the only way this could change: a header edit that
/// included `<string.h>` or `<math.h>` would put the C library's declarations
/// into the translation, and a build that had not listed them would demand them
/// of the provider, which does not export them. Nothing here is routed by
/// mistake today; the list is the statement that there is nothing to route past.
///
/// The authoritative record of what *was* routed is the `symbols` array in the
/// generated dispatch, which the generator fills from what the translation step
/// actually produced.
const libc_noise = "";

/// `extern` declarations the provider may legitimately not export.
///
/// None. All eleven declarations in `zig/bridge.h` are unconditional, are
/// defined unconditionally by `zig/bridge.cc`, and are the complete externally
/// linked ABI this package publishes
/// (`build_support/graph.zig:bridge_abi_symbols`). Nothing about any of them is
/// gated on an optimization mode, a target feature or a configuration macro:
/// there is no `#if` around any definition in the bridge, and upstream's
/// `SIMDJSON_IMPLEMENTATION_*` and `SIMDJSON_BUILTIN_IMPLEMENTATION` switches
/// (`src/include/simdjson/implementation_detection.h:28-175`) select an
/// implementation *inside* the provider, never an entry point. So a provider
/// either exports all eleven or it is refused. It is spelled out so that a
/// future header with an optional entry point is a build-file change with a name
/// in it.
const provider_optional = "";

/// `extern` declarations this build does not require a provider to export.
///
/// None. All eleven functions the translated header declares are expected from a
/// provider, and a provider that does not export one of them is refused rather
/// than half used: there is no fallback route to a second copy, which is the
/// whole contract of the mode.
///
/// A name here is routed and optional rather than direct; only `libc_noise`
/// above stays direct.
const provider_excluded = "";

/// The loader core, for a *linked* build to import.
///
/// A linked build has no dispatch, so the facade needs the core module itself
/// for the two public types `LoadSource` and `LoadError`: they are this SDK's
/// types and they must be the same types a caller names in either
/// configuration. It costs a linked build two declarations and no code, since
/// nothing else in that module is referenced until a configuration actually
/// instantiates the loader.
///
/// A runtime-loading build must *not* import this separately: `createModule`
/// makes the one core instance the dispatch uses, and the dispatch re-exports
/// the two types from it. Two instances would be two sets of types, and a
/// consumer would be naming one while `load` expects the other.
pub fn createCoreModule(
    b: *std.Build,
    target: std.Build.ResolvedTarget,
    optimize: std.builtin.OptimizeMode,
) *std.Build.Module {
    return b.createModule(.{
        .root_source_file = b.path("runtime/loader.zig"),
        .target = target,
        .optimize = optimize,
        // The Unix backend calls `dlopen`, which is libc. Nothing in this module
        // is compiled into a linked build, so this costs nothing there.
        .link_libc = true,
    });
}

/// The runtime-loaded `c` module for one target.
///
/// `translate` is the translation step for that same target and configuration;
/// its output is read by the generator, so the dispatch describes the header
/// this build actually selected rather than another one. It is the very step
/// `build_support/graph.zig` already built for the bridge header, which is what
/// keeps `zig/root.zig`'s `c` the same namespace in both configurations: the
/// dispatch re-exports the translation's own declarations rather than compiling
/// a second, nominally distinct copy of them.
pub fn createModule(
    b: *std.Build,
    translate: *std.Build.Step.TranslateC,
    target: std.Build.ResolvedTarget,
    optimize: std.builtin.OptimizeMode,
) *std.Build.Module {
    const core = createCoreModule(b, target, optimize);

    const library = b.createModule(.{
        .root_source_file = b.path("runtime/library.zig"),
        .target = target,
        .optimize = optimize,
    });
    library.addImport("rt", core);

    return createDispatchModule(b, translate, target, optimize, core, library);
}

const GeneratedSources = struct {
    native: std.Build.LazyPath,
    dispatch: std.Build.LazyPath,
};

fn createDispatchModule(
    b: *std.Build,
    translate: *std.Build.Step.TranslateC,
    target: std.Build.ResolvedTarget,
    optimize: std.builtin.OptimizeMode,
    core: *std.Build.Module,
    library: *std.Build.Module,
) *std.Build.Module {
    const sources = generateDispatch(b, translate, target);

    const dispatch = b.createModule(.{
        .root_source_file = sources.dispatch,
        .target = target,
        .optimize = optimize,
        .link_libc = true,
    });
    dispatch.addImport("rt", core);
    dispatch.addImport("library", library);
    // The translated header, under a name that says what it is. Every constant
    // in the dispatch is re-exported from here rather than restated, so
    // `c.SIMDJSON_BRIDGE_OK` in a facade and `c_native.SIMDJSON_BRIDGE_OK` in the
    // dispatch are one value with one spelling.
    //
    // The root is the generator's *patched* translation, not the raw one the
    // translate step wrote. `const __root = @import("c_routed");` is what makes
    // a macro-expanded declaration that names a library function resolve to the
    // routed wrapper rather than escaping to a native `extern` this route never
    // links. That repointing is why the two modules import each other.
    //
    // `zig/bridge.h` declares three enumerations and one struct and no type at
    // all that needs sharing, so there is nothing here that has to be forwarded
    // as a Zig-side mirror; the constants alone are the whole shared surface.
    const native = b.createModule(.{
        .root_source_file = sources.native,
        .target = target,
        .optimize = optimize,
        .link_libc = true,
    });
    native.addImport("c_routed", dispatch);
    dispatch.addImport("c_native", native);
    dispatch.addCSourceFiles(.{
        .files = &.{"runtime/sync.c"},
        .flags = &.{b.fmt("-DRT_SYNC_PREFIX={s}", .{sync_prefix})},
        .language = .c,
    });
    return dispatch;
}

/// Runs the generator over the translation step's real output.
///
/// The generator is a host program built and run by this build, so the dispatch
/// is produced for the target being built from that target's own translation.
/// Nothing is cached across configurations: a different header configuration
/// produces a different translation step output, which produces a different
/// dispatch.
fn generateDispatch(
    b: *std.Build,
    translate: *std.Build.Step.TranslateC,
    target: std.Build.ResolvedTarget,
) GeneratedSources {
    const generator = b.addExecutable(.{
        .name = b.fmt("simdjson-runtime-generate-{s}", .{
            target.result.zigTriple(b.allocator) catch @panic("unspellable target"),
        }),
        .root_module = b.createModule(.{
            .root_source_file = b.path("runtime/generate.zig"),
            .target = b.graph.host,
            .optimize = .Debug,
        }),
    });

    const run = b.addRunArtifact(generator);
    run.addArg("--library");
    run.addArg(library_name);
    run.addArg("--translate");
    run.addFileArg(translate.getOutput());
    if (libc_noise.len != 0) {
        run.addArg("--noise");
        run.addArg(libc_noise);
    }
    if (provider_optional.len != 0) {
        run.addArg("--optional");
        run.addArg(provider_optional);
    }
    if (provider_excluded.len != 0) {
        run.addArg("--exclude");
        run.addArg(provider_excluded);
    }
    run.addArg("--native-output");
    const native_source = run.addOutputFileArg("native.zig");
    run.addArg("--output");
    const dispatch_source = run.addOutputFileArg("dispatch.zig");
    return .{ .native = native_source, .dispatch = dispatch_source };
}